using IKP.Domain.Common.Base;
using IKP.Domain.Common.Interfaces.Audit;

namespace IKP.Domain.Entities.Reports.Lookups;

/// <summary>
/// Defines a report that can be generated by the server.
/// </summary>
public sealed class ReportDefinition : FullLookupLocalized, IAuditable
{
    public Guid CategoryId { get; set; }
    public bool IsHtmlDescription { get; set; }

    public DateTime CreatedAt { get; set; }
    public Guid? CreatedBy { get; set; }
    public DateTime? UpdatedAt { get; set; }
    public Guid? UpdatedBy { get; set; }

    public ReportCategory Category { get; set; } = null!;
}
